package bw.co.starsign.security;

import java.time.Duration;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Connection to Keycloak Authorization Services for the confidential {@code starsign-api} client
 * (realm and permissions generated by {@code keycloak/generate_authz.py}).
 * <p>
 * A class rather than a record so it can be proxied (records are final).
 */
@ConfigurationProperties("app.keycloak.authz")
public class KeycloakAuthzProperties {

    /** Keycloak base URL, e.g. {@code https://auth.example.com}. */
    private String serverUrl;

    private String realm = "starsign";

    /** Resource server client id. */
    private String clientId = "starsign-api";

    /** Resource server client secret. */
    private String clientSecret;

    /** Upper bound for caching a token's permissions (never past token expiry). */
    private Duration permissionCacheTtl = Duration.ofMinutes(5);

    /** Upper bound for keeping an entry in the in-process (Caffeine) cache in front of Redis. */
    private Duration localCacheTtl = Duration.ofMinutes(1);

    /** Maximum number of entries in the in-process cache. */
    private long localCacheMaxSize = 10_000;

    public String serverUrl() {
        return serverUrl;
    }

    public void setServerUrl(String serverUrl) {
        this.serverUrl = serverUrl;
    }

    public String realm() {
        return realm;
    }

    public void setRealm(String realm) {
        this.realm = realm;
    }

    public String clientId() {
        return clientId;
    }

    public void setClientId(String clientId) {
        this.clientId = clientId;
    }

    public String clientSecret() {
        return clientSecret;
    }

    public void setClientSecret(String clientSecret) {
        this.clientSecret = clientSecret;
    }

    public Duration permissionCacheTtl() {
        return permissionCacheTtl;
    }

    public void setPermissionCacheTtl(Duration permissionCacheTtl) {
        this.permissionCacheTtl = permissionCacheTtl;
    }

    public Duration localCacheTtl() {
        return localCacheTtl;
    }

    public void setLocalCacheTtl(Duration localCacheTtl) {
        this.localCacheTtl = localCacheTtl;
    }

    public long localCacheMaxSize() {
        return localCacheMaxSize;
    }

    public void setLocalCacheMaxSize(long localCacheMaxSize) {
        this.localCacheMaxSize = localCacheMaxSize;
    }
}
